// Browser ports of the supplied Anyloc views. Source mapping: INTERFACE-SOURCES.md.
// All changes are in-memory demo state; this module never contacts a product API.
const paths={check:'m5 12 4 4L19 6',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',wave:'M7 9a5 5 0 0 1 0 6 M11 5a10 10 0 0 1 0 14 M15 2a14 14 0 0 1 0 20',building:'M3 21V7h8v14 M11 21V3h10v18 M6 10h2m-2 4h2m7-7h2m-2 4h2m-2 4h2',list:'M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1',person:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 22v-3a8 8 0 0 1 16 0v3',file:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8',back:'m14 5-7 7 7 7',plus:'M12 4v16M4 12h16',copy:'M8 8h13v13H8zM16 4V1H1v15h3',arrow:'M4 12h16m-6-6 6 6-6 6',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0'};
export const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const escapeHtml=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photo=(file='technical-room')=>`assets/${file}.png`;
const people=[['Екатерина Васильева','ekaterina.vasilyeva','09:20'],['Михаил Крылов','mikhail.krylov','09:35']];
let taskDone=false, reportText='Проверка оборудования завершена. Отклонений не выявлено.';
export function presence(){return `<div class="product-ui pu-presence"><div class="pu-toolbar"><h3>Присутствие</h3><label><input type="checkbox" data-active-only checked> Только активные</label></div><div class="pu-segments" role="group" aria-label="Группировка присутствия"><button data-group="engineers" aria-pressed="true">По сотрудникам</button><button data-group="objects" aria-pressed="false">По объектам</button></div><div class="pu-matrix" data-matrix>${matrix('engineers',true)}</div><div class="pu-legend"><i></i> Активная сессия</div></div>`;}
function matrix(group,active){const rows=group==='engineers'?people.map(p=>`<div class="pu-person"><strong>${p[0]}</strong><small>${p[1]}</small></div><div class="pu-cell"><button class="pu-session" data-session="${p[0]}"><strong>Школа №18 <i></i></strong><span>${icon('clock')}${p[2]}:00 – сейчас</span></button></div>`).join(''):`<div class="pu-person"><strong>Школа №18</strong><small>Техническое обслуживание</small></div><div class="pu-cell">${people.map(p=>`<button class="pu-session" data-session="${p[0]}"><strong>${p[0]}</strong><span>${icon('clock')}${p[2]}:00 – сейчас</span></button>`).join('')}</div>`;return `<div class="pu-matrix-label">${group==='engineers'?'Сотрудник':'Объект'}</div><div class="pu-day"><strong>Среда <small>Сегодня</small></strong><span>23 сент.</span></div>${rows}${!active?'<div class="pu-person"><strong>Алексей Воронов</strong><small>alexey.voronov</small></div><div class="pu-cell"><div class="pu-session pu-ended"><strong>БЦ Орион</strong><span>08:00:00 – 10:15:00</span></div></div>':''}`;}
export function report(service=false){return `<div class="product-ui pu-report"><div class="pu-document-top">${service?'Обслуживание':'Детали отчета'}<button class="pu-icon-button" data-copy aria-label="Скопировать текст отчета">${icon('copy')}</button></div><div class="pu-document-body"><small class="pu-code">ОТЧ-REPORT-02</small><h3>${service?'Проверка оборудования':escapeHtml(reportText)}</h3><dl class="pu-report-meta"><div><dt>Дата и время</dt><dd>23 сент. 2026 г., 10:24</dd></div><div><dt>Инженер</dt><dd>Алексей Воронов</dd></div><div class="pu-object"><dt>Объект</dt><dd>БЦ Орион<small>Москва, ул. Тверская, 10</small><span>Метка</span>Техническое помещение</dd></div></dl>${service?'<div class="pu-work-result"><h4>Результат выполненных работ</h4><p>Работы за смену выполнены по плану. Отклонения и замечания, требующие срочного решения, не зафиксированы.</p></div>':''}<div class="pu-attachments-title">Вложения (2)</div><div class="pu-attachments"><button data-photo="technical-room" aria-label="Открыть фото технического помещения"><img src="${photo()}" alt="Техническое помещение"><span>Фото · technical-room.png</span></button><button data-photo="utility-inspection" aria-label="Открыть фото осмотра"><img src="${photo('utility-inspection')}" alt="Осмотр оборудования"><span>Фото · utility-inspection.png</span></button></div></div></div>`;}
export function journal(){return `<div class="product-ui pu-journal"><div class="pu-toolbar"><h3>Журнал</h3><select aria-label="Тип события" data-event-filter><option value="all">Все типы</option><option>Вход</option><option>Отчёт</option><option>Выход</option></select></div><table><thead><tr><th>Дата и время</th><th>Сотрудник</th><th>Тип</th><th>Метка / отчёт</th></tr></thead><tbody>${[['10:24','Алексей Воронов','Отчёт','Проверка оборудования'],['09:35','Михаил Крылов','Вход','Школа №18'],['09:20','Екатерина Васильева','Вход','Школа №18'],['08:50','Алексей Воронов','Выход','БЦ Орион']].map(r=>`<tr data-event="${r[2]}"><td><time>23.09.2026<br>${r[0]}</time></td><td><strong>${r[1]}</strong></td><td><span class="pu-badge ${r[2]==='Отчёт'?'purple':'green'}">${r[2]}</span></td><td>${r[2]==='Отчёт'?`<button data-open-ui="report">${r[3]} ↗</button>`:r[3]}</td></tr>`).join('')}</tbody></table></div>`;}
export function tasks(){return `<div class="product-ui pu-tasks"><div class="pu-toolbar"><h3>Глобальные задачи</h3></div><div class="pu-task-counters"><span class="pu-badge">Открыто: ${taskDone?1:2}</span><span class="pu-badge green">Закрыто: ${taskDone?1:0}</span></div><div class="pu-segments" role="group" aria-label="Статус задач"><button data-task-filter="all" aria-pressed="true">Все</button><button data-task-filter="open" aria-pressed="false">Открытые</button><button data-task-filter="completed" aria-pressed="false">Закрытые</button></div><div class="pu-task-list"><article data-task-state="${taskDone?'completed':'open'}"><button class="pu-task-check" data-complete aria-label="${taskDone?'Вернуть задачу в работу':'Завершить задачу'}" aria-pressed="${taskDone}">${taskDone?icon('check'):''}</button><div><strong class="${taskDone?'pu-done':''}">Сделать СКУД на Горбушке, 4 двери</strong><span class="pu-badge amber">⚑ Высокий</span><p>Прокинуть кабель, подготовить точки подключения и закрыть монтажный этап.</p><div class="pu-task-assignee">Алексей Воронов <span>${taskDone?'Выполнено':'В работе'}</span></div></div></article><article data-task-state="open"><span class="pu-task-check" aria-hidden="true"></span><div><strong>Проверить оборудование на объекте</strong><span class="pu-badge">Средний</span><p>Проверить подключение и работу контроллера.</p><div class="pu-task-assignee">Михаил Крылов <span>В работе</span></div></div></article></div><p class="pu-empty" hidden>Ничего не найдено</p></div>`;}
export function adminView(key){return key==='presence'?presence():key==='tasks'?tasks():key==='journal'?journal():report(key==='service');}
function iosHeader(title){return `<header class="ios-header"><span><img src="assets/favicon.png" alt=""></span><b>${title}</b></header>`;}
function iosAuxiliary(key){return key==='profile'?`${iosHeader('Профиль')}<div class="ios-profile"><div class="ios-profile-icon">${icon('person')}</div><h3>Алексей Воронов</h3><p>Инженер</p><div class="ios-profile-info"><div>${icon('building')}<span><small>КОМПАНИЯ</small><b>СМК</b></span></div><div>${icon('person')}<span><small>ЛОГИН</small><b>alexey.voronov</b></span></div></div></div>`:`${iosHeader('Задачи')}<div class="ios-task-list"><article><button data-ios-complete aria-label="${taskDone?'Открыть задачу':'Закрыть задачу'}" aria-pressed="${taskDone}">${taskDone?icon('check'):''}</button><div><p class="${taskDone?'pu-done':''}">Сделать СКУД на Горбушке, 4 двери</p><time>25 сент. 2026</time></div></article><article><span class="ios-task-circle"></span><div><p>Проверить оборудование на объекте</p><time>24 сент. 2026</time></div></article></div>`;}
export function phoneMarkup(){return `<div class="al-phone-scene" data-step-view="0"><div class="al-phone-orbit" aria-hidden="true"></div><div class="al-phone ios-device"><div class="ios-viewport"><div class="ios-app"><div class="ios-status"><span>9:41</span><span>••• ▰</span></div><div class="ios-island" aria-hidden="true"></div><div class="al-phone-pages"><div class="al-phone-page" id="phone-step-0" role="tabpanel" aria-labelledby="step-tab-0">${iosHeader('Объекты')}<div class="ios-search">${icon('search')} Поиск объектов</div><div class="ios-facility"><b>БЦ Орион</b><p>Москва, ул. Тверская, 10</p><span>Техническое обслуживание</span></div><div class="ios-sheet"><i class="ios-handle"></i><div class="ios-success-heading"><span>${icon('check')}</span><div><b>Успешно отправлено</b><p>09:41:00</p></div></div><dl class="ios-result"><div><dt>Сотрудник</dt><dd>Алексей Воронов</dd></div><div><dt>Объект</dt><dd>БЦ Орион</dd></div></dl><button class="ios-primary" data-phone-next="1">Закрыть</button></div></div><div class="al-phone-page" id="phone-step-1" role="tabpanel" aria-labelledby="step-tab-1" hidden>${iosHeader('Отчет')}<div class="ios-scroll"><button class="ios-back" data-phone-next="0">${icon('back')} Назад к объекту</button><div class="ios-object"><b>БЦ Орион</b><p>Москва, ул. Тверская, 10</p></div><form class="ios-report-form"><div class="ios-editor"><textarea aria-label="Текст отчёта" maxlength="2000" placeholder="Подробно опишите ситуацию или происшествие...">${reportText}</textarea><small data-char-count>${reportText.length} / 2000</small><div class="ios-attachment-heading"><b>Вложения · <span data-attachment-count>1</span></b><button type="button" data-ios-add aria-label="Добавить вложение">${icon('plus')}</button></div><div class="ios-draft-photos"><button type="button" data-photo="technical-room" aria-label="Открыть вложение technical-room.png"><img src="${photo()}" alt="Техническое помещение"><span>technical-room.png</span></button></div></div><button class="ios-primary" type="submit">Отправить отчет</button></form></div></div><div class="al-phone-page" id="phone-step-2" role="tabpanel" aria-labelledby="step-tab-2" hidden>${iosHeader('История')}<div class="ios-history"><div class="ios-week"><div><small>РАБОЧИЕ ЧАСЫ ЗА НЕДЕЛЮ</small><strong>18 ч 42 мин</strong><span>21–27 сентября</span></div>${icon('clock')}</div><h4>СЕГОДНЯ</h4>${[['file','Отчет отправлен','БЦ Орион','10:24','blue'],['check','Отметка объекта','БЦ Орион','10:20','purple'],['arrow','Начало работы','БЦ Орион','09:41','green']].map(r=>`<div class="ios-activity"><span class="ios-activity-icon ${r[4]}">${icon(r[0])}</span><div><b>${r[1]}</b><p>${r[2]}</p></div><time>${r[3]}</time></div>`).join('')}</div></div></div><nav class="ios-dock" aria-label="Разделы мобильного приложения">${[['building','Объекты',0],['list','Задачи','tasks'],['wave','Скан',0],['clock','История',2],['person','Профиль','profile']].map(r=>`<button data-ios-nav="${r[2]}" aria-label="${r[1]}">${icon(r[0])}<small>${r[1]}</small></button>`).join('')}</nav><div class="ios-home-indicator" aria-hidden="true"></div><div class="ios-toast" role="status" hidden>Отчет отправлен</div></div></div></div><div class="al-floating-receipt"><span class="al-receipt-check">✓</span><div><small>ANYLOC / СОБЫТИЕ</small><strong id="phone-receipt">Отметка сохранена</strong></div><span>↗</span></div><span class="al-phone-caption">Дизайн приложения iOS · интерактивный пример</span></div>`;}
export function bindProductUI(root,{open,step}){
 root.addEventListener('click',async event=>{
  const b=event.target.closest('button');if(!b)return;
  if(b.dataset.openUi)open(b.dataset.openUi);
  if(b.dataset.photo)open('photo',b.dataset.photo);
  if(b.dataset.group){const panel=b.closest('.pu-presence');panel.querySelectorAll('[data-group]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));panel.querySelector('[data-matrix]').innerHTML=matrix(b.dataset.group,panel.querySelector('[data-active-only]').checked);}
  if(b.dataset.session){open('session',b.dataset.session);}
  if(b.hasAttribute('data-copy')){try{await navigator.clipboard.writeText(b.closest('.pu-report').querySelector('h3').textContent);b.innerHTML=icon('check');b.setAttribute('aria-label','Текст скопирован');}catch{b.setAttribute('aria-label','Не удалось скопировать');}}
  if(b.hasAttribute('data-complete')){taskDone=!taskDone;const panel=b.closest('.pu-tasks');panel.outerHTML=tasks();}
  if(b.dataset.taskFilter){const panel=b.closest('.pu-tasks');panel.querySelectorAll('[data-task-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));panel.querySelectorAll('[data-task-state]').forEach(x=>x.hidden=b.dataset.taskFilter!=='all'&&x.dataset.taskState!==b.dataset.taskFilter);panel.querySelector('.pu-empty').hidden=!!panel.querySelector('[data-task-state]:not([hidden])');}
  if(b.dataset.phoneNext)step(Number(b.dataset.phoneNext));
  if(b.dataset.iosNav){let aux=root.querySelector('.ios-aux');if(!aux){aux=document.createElement('div');aux.className='ios-aux';root.querySelector('.ios-app').append(aux);}if(b.dataset.iosNav==='tasks'||b.dataset.iosNav==='profile'){aux.innerHTML=iosAuxiliary(b.dataset.iosNav);aux.hidden=false;}else{aux.hidden=true;step(Number(b.dataset.iosNav));}root.querySelectorAll('[data-ios-nav]').forEach(x=>x.setAttribute('aria-current',String(x===b)));}
  if(b.hasAttribute('data-ios-complete')){taskDone=!taskDone;b.closest('.ios-aux').innerHTML=iosAuxiliary('tasks');}
  if(b.hasAttribute('data-ios-add')){const form=b.closest('form');if(form.querySelectorAll('.ios-draft-photos>button').length<2){form.querySelector('.ios-draft-photos').insertAdjacentHTML('beforeend',`<button type="button" data-photo="utility-inspection" aria-label="Открыть фото осмотра"><img src="${photo('utility-inspection')}" alt="Осмотр оборудования"><span>utility-inspection.png</span></button>`);form.querySelector('[data-attachment-count]').textContent='2';}b.disabled=true;}
 });
 root.addEventListener('input',event=>{if(event.target.matches('.ios-editor textarea')){reportText=event.target.value;event.target.parentElement.querySelector('[data-char-count]').textContent=`${reportText.length} / 2000`;}});
 root.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-active-only]')){const panel=el.closest('.pu-presence');panel.querySelector('[data-matrix]').innerHTML=matrix(panel.querySelector('[data-group][aria-pressed=true]').dataset.group,el.checked);}if(el.matches('[data-event-filter]'))el.closest('.pu-journal').querySelectorAll('[data-event]').forEach(row=>row.hidden=el.value!=='all'&&row.dataset.event!==el.value);});
 root.addEventListener('submit',event=>{if(!event.target.matches('.ios-report-form'))return;event.preventDefault();if(!reportText.trim()){event.target.querySelector('textarea').focus();return;}step(2);const toast=root.querySelector('.ios-toast');toast.hidden=false;setTimeout(()=>toast.hidden=true,1800);});
}
export function detailView(key,value){if(key==='photo')return `<img class="pu-full-photo" src="${photo(value)}" alt="Фото из отчёта">`;if(key==='profile')return `<div class="product-ui pu-profile"><h3>Профиль</h3>${icon('person')}<h4>Алексей Воронов</h4><p>Инженер</p><p>Демонстрационный профиль</p></div>`;if(key==='session')return `<div class="product-ui pu-session-detail"><h3>Рабочее время</h3><h4>${escapeHtml(value)}</h4><p>Школа №18</p><dl><div><dt>Начало</dt><dd>${value===people[0][0]?'09:20':'09:35'}</dd></div><div><dt>Окончание</dt><dd>На объекте</dd></div></dl></div>`;return adminView(key);}
